    19	    public static Javalin create(ReservationService service, List<Report<?>> reports) {
    20	        ObjectMapper mapper = new ObjectMapper()
    21	                .registerModule(new JavaTimeModule())
    22	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    23	                .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
    24	
    25	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
    26	
    27	        app.exception(ApiException.class, (e, ctx) -> ctx.status(e.status()).json(error(e.code(), e.getMessage())));
    28	        app.exception(Exception.class, (e, ctx) -> {
    29	            e.printStackTrace();
    30	            ctx.status(500).json(error("INTERNAL_ERROR", "Erro interno"));
    31	        });
    32	        app.error(404, ctx -> {
    33	            if (ctx.result() == null || ctx.result().isEmpty()) {
    34	                ctx.json(error("NOT_FOUND", "Recurso não encontrado"));
    35	            }
    36	        });
    37	
    38	        app.get("/rooms", ctx -> ctx.json(service.rooms()));
    39	        app.post("/reservations", ctx -> {
    40	            ReservationRequest request = ReservationRequest.parse(readBody(mapper, ctx.body()));
    41	            ctx.status(201).json(service.create(request));
    42	        });
    43	        app.get("/reservations/{id}", ctx -> ctx.json(service.get(ctx.pathParam("id"))));
    44	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(service.confirm(ctx.pathParam("id"))));
    45	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(service.cancel(ctx.pathParam("id"))));
    46	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(service.checkIn(ctx.pathParam("id"))));
    47	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(ctx.pathParam("id"))));
    48	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(ctx.pathParam("id"))));
    49	        app.get("/messages", ctx -> ctx.json(service.messages()));
    50	
