     9	    public interface Work<T> {
    10	        T apply(Connection connection) throws SQLException;
    11	    }
    12	
    13	    private final String url;
    14	    private final String user;
    15	    private final String password;
    16	
    17	    public Db(String url, String user, String password) {
    18	        this.url = url;
    19	        this.user = user;
    20	        this.password = password;
    21	    }
    22	
    23	    public Connection open() throws SQLException {
    24	        return DriverManager.getConnection(url, user, password);
    25	    }
    26	
    27	    /** Executa o trabalho numa transação: confirma se terminar bem, desfaz se falhar. */
    28	    public <T> T tx(Work<T> work) {
    29	        try (Connection connection = open()) {
    30	            connection.setAutoCommit(false);
    31	            try {
    32	                T result = work.apply(connection);
    33	                connection.commit();
    34	                return result;
    35	            } catch (Throwable e) {
    36	                connection.rollback();
    37	                throw e;
    38	            }
    39	        } catch (SQLException e) {
    40	            throw new IllegalStateException("Erro no banco de dados", e);
    41	        }
    42	    }
