     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Pricing() {
    11	    }
    12	
    13	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    14	    }
    15	
    16	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    17	    public static boolean isHighSeason(LocalDate night) {
    18	        Month month = night.getMonth();
    19	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    20	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    21	    }
    22	
    23	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    24	        BigDecimal rate = room.nightlyRate();
    25	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : Money.round(rate);
    26	    }
    27	
    28	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    29	        BigDecimal subtotal = Money.ZERO;
    30	        int nights = 0;
    31	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    32	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    33	            nights++;
    34	        }
    35	        BigDecimal discount = plan.discountOn(subtotal);
    36	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    37	    }
    38	}
