    19	            FROM reservations
    20	            """;
    21	
    22	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    23	        String sql = """
    24	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests,
    25	                  rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    26	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    27	                """;
    28	        try (PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    29	            ps.setInt(1, r.roomNumber());
    30	            ps.setString(2, r.guestName());
    31	            ps.setString(3, r.guestEmail());
    32	            ps.setString(4, r.guestCpf());
    33	            ps.setDate(5, Date.valueOf(r.checkIn()));
    34	            ps.setDate(6, Date.valueOf(r.checkOut()));
    35	            ps.setInt(7, r.guests());
    36	            ps.setString(8, r.ratePlan().name());
    37	            ps.setInt(9, r.nights());
    38	            ps.setBigDecimal(10, r.subtotal());
    39	            ps.setBigDecimal(11, r.discount());
    40	            ps.setBigDecimal(12, r.total());
    41	            ps.setString(13, r.status().name());
    42	            ps.setBigDecimal(14, r.amountPaid());
    43	            ps.setBigDecimal(15, r.refund());
    44	            ps.executeUpdate();
    45	            try (ResultSet keys = ps.getGeneratedKeys()) {
    46	                keys.next();
    47	                return r.withId(keys.getLong("id"));
    48	            }
    49	        }
    50	    }
    51	
    52	    public void update(Connection c, Reservation r) throws SQLException {
    53	        try (PreparedStatement ps = c.prepareStatement(
    54	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    55	            ps.setString(1, r.status().name());
    56	            ps.setBigDecimal(2, r.amountPaid());
    57	            ps.setBigDecimal(3, r.refund());
    58	            ps.setLong(4, r.id());
