    63	    public Optional<Reservation> find(Connection c, long id, boolean lock) throws SQLException {
    64	        List<Reservation> found = query(c, "WHERE id = ?" + (lock ? " FOR UPDATE" : ""), ps -> ps.setLong(1, id));
    65	        return found.stream().findFirst();
    66	    }
    67	
    68	    /** Reservas não canceladas do quarto que ocupam alguma das noites de [checkIn, checkOut). */
    69	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    70	        try (PreparedStatement ps = c.prepareStatement("""
    71	                SELECT 1 FROM reservations
    72	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    73	                """)) {
    74	            ps.setInt(1, roomNumber);
    75	            ps.setDate(2, Date.valueOf(checkOut));
    76	            ps.setDate(3, Date.valueOf(checkIn));
    77	            try (ResultSet rs = ps.executeQuery()) {
    78	                return rs.next();
    79	            }
    80	        }
    81	    }
    82	
    83	    /** Reservas que começam no mês, por data de entrada e depois por número. */
    84	    public List<Reservation> startingIn(Connection c, YearMonth month) throws SQLException {
    85	        return query(c, "WHERE check_in >= ? AND check_in < ? ORDER BY check_in, id", ps -> {
    86	            ps.setDate(1, Date.valueOf(month.atDay(1)));
    87	            ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
    88	        });
    89	    }
    90	
    91	    /** Reservas que ocupam um quarto na noite informada, por número do quarto. */
    92	    public List<Reservation> occupying(Connection c, LocalDate night) throws SQLException {
    93	        return query(c, "WHERE check_in <= ? AND check_out > ? ORDER BY room_number, id", ps -> {
    94	            ps.setDate(1, Date.valueOf(night));
    95	            ps.setDate(2, Date.valueOf(night));
    96	        });
    97	    }
