    99	    private interface Binder {
   100	        void bind(PreparedStatement ps) throws SQLException;
   101	    }
   102	
   103	    private List<Reservation> query(Connection c, String tail, Binder binder) throws SQLException {
   104	        try (PreparedStatement ps = c.prepareStatement(SELECT + tail)) {
   105	            binder.bind(ps);
   106	            try (ResultSet rs = ps.executeQuery()) {
   107	                List<Reservation> list = new ArrayList<>();
   108	                while (rs.next()) {
   109	                    list.add(map(rs));
   110	                }
   111	                return list;
   112	            }
   113	        }
   114	    }
   115	
   116	    private static Reservation map(ResultSet rs) throws SQLException {
   117	        return new Reservation(
   118	                rs.getLong("id"),
   119	                rs.getInt("room_number"),
   120	                rs.getString("guest_name"),
   121	                rs.getString("guest_email"),
   122	                rs.getString("guest_cpf"),
   123	                rs.getDate("check_in").toLocalDate(),
   124	                rs.getDate("check_out").toLocalDate(),
   125	                rs.getInt("guests"),
   126	                RatePlan.valueOf(rs.getString("rate_plan")),
   127	                rs.getInt("nights"),
   128	                rs.getBigDecimal("subtotal"),
   129	                rs.getBigDecimal("discount"),
   130	                rs.getBigDecimal("total"),
   131	                ReservationStatus.valueOf(rs.getString("status")),
