    12	    public static ReservationRequest parse(JsonNode body) {
    13	        if (body == null || !body.isObject()) {
    14	            throw ApiException.invalidRequest("O corpo deve ser um objeto JSON");
    15	        }
    16	        LocalDate checkIn = date(body, "checkIn");
    17	        LocalDate checkOut = date(body, "checkOut");
    18	        if (!checkOut.isAfter(checkIn)) {
    19	            throw ApiException.invalidRequest("A saída deve ser depois da entrada");
    20	        }
    21	        int guests = integer(body, "guests");
    22	        if (guests < 1) {
    23	            throw ApiException.invalidRequest("É preciso pelo menos um hóspede");
    24	        }
    25	        return new ReservationRequest(integer(body, "roomNumber"), text(body, "guestName"), text(body, "guestEmail"),
    26	                text(body, "guestCpf"), checkIn, checkOut, guests, ratePlan(body));
    27	    }
    28	
    29	    private static String text(JsonNode body, String field) {
    30	        JsonNode node = body.get(field);
    31	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    32	            throw ApiException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    33	        }
    34	        return node.asText();
    35	    }
    36	
    37	    private static int integer(JsonNode body, String field) {
    38	        JsonNode node = body.get(field);
    39	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    40	            throw ApiException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    41	        }
    42	        return node.asInt();
    43	    }
    44	
    45	    private static LocalDate date(JsonNode body, String field) {
    46	        String value = text(body, field);
    47	        try {
    48	            return LocalDate.parse(value);
    49	        } catch (DateTimeParseException e) {
    50	            throw ApiException.invalidRequest("Data inválida em " + field + " (use AAAA-MM-DD)");
    51	        }
    52	    }
    53	
    54	    private static RatePlan ratePlan(JsonNode body) {
    55	        String value = text(body, "ratePlan");
    56	        try {
    57	            return RatePlan.valueOf(value);
    58	        } catch (IllegalArgumentException e) {
    59	            throw ApiException.invalidRequest("Plano de tarifa inválido: " + value);
    60	        }
    61	    }
