    29	    public Reservation create(ReservationRequest request) {
    30	        return db.tx(c -> {
    31	            Room room = rooms.findForUpdate(c, request.roomNumber())
    32	                    .orElseThrow(() -> ApiException.roomNotFound(request.roomNumber()));
    33	            if (request.guests() > room.capacity()) {
    34	                throw ApiException.capacityExceeded(room.capacity());
