    39	            Pricing.Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    40	            return reservations.insert(c, new Reservation(null, room.number(), request.guestName(),
    41	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(),
    42	                    request.ratePlan(), quote.nights(), quote.subtotal(), quote.discount(), quote.total(),
    43	                    ReservationStatus.PENDING, Money.ZERO, null));
    44	        });
