    78	            }
    79	            return receiptOf(c, r);
    80	        });
    81	    }
    82	
    83	    private Reservation apply(Connection c, String id, UnaryOperator<Reservation> change) throws SQLException {
    84	        Reservation changed = change.apply(load(c, id, true));
    85	        reservations.update(c, changed);
