     1	package pousada;
     2	
     3	import java.sql.Connection;
     4	import java.sql.PreparedStatement;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	import java.util.List;
     8	
     9	/** Cria no banco o que o sistema precisa e cadastra os quartos da pousada. */
    10	public final class Schema {
    11	    private static final List<Room> ROOMS = List.of(
    12	            new Room(101, RoomType.STANDARD, 2, Money.of("249.90")),
    13	            new Room(102, RoomType.STANDARD, 2, Money.of("249.90")),
    14	            new Room(201, RoomType.DELUXE, 3, Money.of("389.90")),
    15	            new Room(202, RoomType.DELUXE, 3, Money.of("389.90")),
    16	            new Room(301, RoomType.SUITE, 4, Money.of("579.90")));
    17	
    18	    private static final List<String> DDL = List.of(
    19	            """
    20	            CREATE TABLE IF NOT EXISTS rooms (
    21	              number INTEGER PRIMARY KEY,
    22	              type VARCHAR(20) NOT NULL,
    23	              capacity INTEGER NOT NULL,
    24	              nightly_rate NUMERIC(12,2) NOT NULL)
    25	            """,
    26	            """
    27	            CREATE TABLE IF NOT EXISTS reservations (
    28	              id BIGSERIAL PRIMARY KEY,
    29	              room_number INTEGER NOT NULL REFERENCES rooms(number),
    30	              guest_name VARCHAR(200) NOT NULL,
    31	              guest_email VARCHAR(200) NOT NULL,
    32	              guest_cpf VARCHAR(30) NOT NULL,
    33	              check_in DATE NOT NULL,
    34	              check_out DATE NOT NULL,
    35	              guests INTEGER NOT NULL,
    36	              rate_plan VARCHAR(20) NOT NULL,
    37	              nights INTEGER NOT NULL,
    38	              subtotal NUMERIC(12,2) NOT NULL,
    39	              discount NUMERIC(12,2) NOT NULL,
    40	              total NUMERIC(12,2) NOT NULL,
    41	              status VARCHAR(20) NOT NULL,
    42	              amount_paid NUMERIC(12,2) NOT NULL,
    43	              refund NUMERIC(12,2))
    44	            """,
    45	            """
    46	            CREATE TABLE IF NOT EXISTS messages (
    47	              id BIGSERIAL PRIMARY KEY,
    48	              channel VARCHAR(20) NOT NULL,
    49	              recipient VARCHAR(200) NOT NULL,
    50	              subject VARCHAR(300) NOT NULL,
    51	              body TEXT NOT NULL)
    52	            """);
    53	
    54	    private Schema() {
    55	    }
    56	
    57	    public static void init(Db db) {
    58	        awaitDatabase(db);
    59	        db.tx(c -> {
    60	            try (Statement lock = c.createStatement()) {
    61	                lock.execute("SELECT pg_advisory_xact_lock(7070)");
    62	            }
    63	            for (String ddl : DDL) {
    64	                try (Statement s = c.createStatement()) {
    65	                    s.execute(ddl);
    66	                }
    67	            }
    68	            for (Room room : ROOMS) {
    69	                insertRoom(c, room);
    70	            }
    71	            return null;
    72	        });
    73	    }
    74	
    75	    private static void insertRoom(Connection c, Room room) throws SQLException {
    76	        try (PreparedStatement ps = c.prepareStatement(
    77	                "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?) ON CONFLICT DO NOTHING")) {
    78	            ps.setInt(1, room.number());
    79	            ps.setString(2, room.type().name());
    80	            ps.setInt(3, room.capacity());
    81	            ps.setBigDecimal(4, room.nightlyRate());
    82	            ps.executeUpdate();
    83	        }
    84	    }
    85	
    86	    private static void awaitDatabase(Db db) {
    87	        SQLException last = null;
    88	        for (int attempt = 0; attempt < 60; attempt++) {
    89	            try (Connection ignored = db.open()) {
    90	                return;
    91	            } catch (SQLException e) {
    92	                last = e;
    93	                try {
    94	                    Thread.sleep(1000);
    95	                } catch (InterruptedException ie) {
    96	                    Thread.currentThread().interrupt();
    97	                    break;
    98	                }
    99	            }
   100	        }
   101	        throw new IllegalStateException("Banco de dados indisponível", last);
   102	    }
   103	}

