    32	        return new ReportData(List.of("reservation", "room", "check_in", "check_out", "guests", "nights", "tax"), rows,
    33	                List.of("total", Money.plain(total)));
    34	    }
    35	
    36	    private BigDecimal taxOf(Reservation r) {
    37	        return Money.round(taxPerGuestNight.multiply(BigDecimal.valueOf((long) r.guests() * r.nights())));
    38	    }
    39	}

