158	
159	    @Test
160	    void highSeasonExample() {
161	        Pricing.Quote q = Pricing.quote(standard, LocalDate.of(2027, 7, 10), LocalDate.of(2027, 7, 12), RatePlan.STANDARD);
162	        assertEquals(2, q.nights());
163	        assertEquals(Money.of("599.76"), q.subtotal());
164	        assertEquals(Money.of("0.00"), q.discount());
165	        assertEquals(Money.of("599.76"), q.total());
166	    }
167	
168	    @Test
169	    void nonRefundableDiscount() {
170	        Pricing.Quote q = Pricing.quote(standard, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 3), RatePlan.NON_REFUNDABLE);
171	        assertEquals(Money.of("499.80"), q.subtotal());
172	        assertEquals(Money.of("74.97"), q.discount());
173	        assertEquals(Money.of("424.83"), q.total());
174	    }
