178	        assertFalse(Pricing.isHighSeason(LocalDate.of(2026, 12, 14)));
179	        assertTrue(Pricing.isHighSeason(LocalDate.of(2026, 12, 15)));
180	        assertTrue(Pricing.isHighSeason(LocalDate.of(2027, 2, 28)));
181	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 3, 1)));
182	        assertTrue(Pricing.isHighSeason(LocalDate.of(2027, 7, 31)));
183	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 8, 1)));
184	    }
