200	                Comprovante de reserva nº 7
201	                Hóspede: Carla Dias (CPF 111.222.333-44)
202	                Quarto: 201 (DELUXE)
203	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
204	                Diárias: R$ 779,80
205	                Total: R$ 779,80""", Receipt.of(r, deluxe).toText());
206	        assertEquals("R$ 1.234,56", Money.brl(Money.of("1234.56")));
207	    }
