141	        assertEquals(receipt, JSON.readTree(send("GET", "/reservations/" + id + "/document", null).body()));
142	        assertEquals(409, send("POST", "/reservations/" + id + "/cancellation", null).statusCode());
143	        assertEquals(404, send("GET", "/reservations/99999", null).statusCode());
144	    }
145	}
